import React from "react";
import { AbsoluteFill, interpolate, spring, useCurrentFrame, useVideoConfig, Img } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');
const loadRobotoMono = makeLoadFont('RobotoMono');

const { fontFamily: interFamily } = loadInter();
const { fontFamily: monoFamily } = loadRobotoMono();



export type SharePointVaultProps = Record<string, any>;

const MOCK_DATA = [
  { id: "101", service: "Production DB", user: "admin_malloy", pass: "tr0ub4dor&3", status: "Active" },
  { id: "102", service: "AWS Root", user: "devops@malloy", pass: "C0mpl3xP@ss!", status: "Active" },
  { id: "103", service: "Payment API", user: "stripe_prod", pass: "sk_live_abc123", status: "Rotated" },
  { id: "104", service: "Admin Portal", user: "superadmin", pass: "admin12345", status: "Active" },
  { id: "105", service: "Email SMTP", user: "noreply_sys", pass: "smtp_pass_99", status: "Active" },
  { id: "106", service: "VPN Access", user: "remote_wk", pass: "vpn_secure_8", status: "Active" },
  { id: "107", service: "Backup Server", user: "backup_svc", pass: "bckp_v2_991", status: "Active" },
  { id: "108", service: "Social Media", user: "marketing_x", pass: "tweet_master", status: "Locked" },
  { id: "109", service: "HR System", user: "hr_admin", pass: "hr_secure_1", status: "Active" },
  { id: "110", service: "Analytics API", user: "data_eng", pass: "data_pipe_9", status: "Active" },
  { id: "111", service: "Support Desk", user: "help_desk", pass: "help_99_123", status: "Active" },
  { id: "112", service: "Staging DB", user: "test_user", pass: "test_pass_1", status: "Active" }
];

const cellStyle: React.CSSProperties = {
  borderRight: '1px solid #e1dfdd',
  padding: '14px 20px',
  display: 'flex',
  alignItems: 'center',
  fontSize: 16,
  color: '#323130',
  boxSizing: 'border-box',
  overflow: 'hidden',
  whiteSpace: 'nowrap'
};

const LOGO_URL = "https://remotionlambda-apsoutheast1-ywsmvwk2tp.s3.ap-southeast-1.amazonaws.com/assets/9ebab274d014453a832d12d5ea5e9fce.png";

const SharePointVault: React.FC<SharePointVaultProps> = ({
  backgroundColor = "#1a1c1e",
  transparentBackground = false,
  durationInSeconds = 10,
  themeColor = "#008272", // Updated to match the teal visual element of the SharePoint logo
  documentTitle = "Malloy_Studio_Vault.xlsx",
  showPasswordsAsAsterisks = true,
  numberOfEntries = 8,
}) => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  const bgColorSafe = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Background pattern opacity
  const bgOpacity = interpolate(frame, [0, 30], [0, 0.1], { extrapolateRight: "clamp" });
  
  // Big Center Logo Animations
  const bigLogoIn = spring({ frame, fps, config: { damping: 12 } });
  const logoAnticipation = spring({ frame: frame - 20, fps, config: { damping: 14 } });
  
  // Spreadsheet Container Animations (animates out from the center logo)
  const spreadSheetSpring = spring({ frame: frame - 30, fps, config: { damping: 14 } });
  
  // Logo scales in, anticipates slightly, then expands outwardly as the spreadsheet pops
  const bigLogoScale = bigLogoIn - (logoAnticipation * 0.15) + (spreadSheetSpring * 0.5); 
  const bigLogoOpacity = interpolate(frame - 30, [0, 5], [1, 0], { extrapolateRight: 'clamp', extrapolateLeft: 'clamp' });

  // Spreadsheet expands perfectly from the exact center (scale 0 to 1)
  const spreadSheetScaleVal = interpolate(spreadSheetSpring, [0, 1], [0, 1]);
  const spreadSheetOpacity = interpolate(frame - 30, [0, 2], [0, 1], { extrapolateRight: 'clamp', extrapolateLeft: 'clamp' });

  const targetDataRowIndex = 2;

  return (
    <AbsoluteFill style={{ backgroundColor: bgColorSafe, fontFamily: interFamily, justifyContent: 'center', alignItems: 'center', transition: 'none' }}>
      
      {/* Background SVG Pattern */}
      <svg style={{ position: 'absolute', width: '100%', height: '100%', opacity: bgOpacity, transition: 'none' }}>
        <defs>
          <pattern id="dotPattern" x="0" y="0" width="40" height="40" patternUnits="userSpaceOnUse">
            <circle cx="2" cy="2" r="2" fill="#ffffff" />
          </pattern>
        </defs>
        <rect x="0" y="0" width="100%" height="100%" fill="url(#dotPattern)" />
      </svg>

      {/* Big Centered SharePoint Logo */}
      <AbsoluteFill style={{ justifyContent: 'center', alignItems: 'center', transition: 'none', zIndex: 1 }}>
        <Img 
          src={LOGO_URL}
          style={{
            width: 320,
            height: 320,
            objectFit: 'contain',
            transform: `scale(${bigLogoScale})`,
            opacity: bigLogoOpacity,
            transition: 'none'
          }}
        />
      </AbsoluteFill>

      {/* Simplified Spreadsheet Application Window */}
      <div style={{
        width: 1200,
        backgroundColor: '#ffffff',
        borderRadius: 16,
        overflow: 'hidden',
        boxShadow: '0 25px 80px rgba(0,0,0,0.3)',
        display: 'flex',
        flexDirection: 'column',
        transform: `scale(${spreadSheetScaleVal})`,
        opacity: spreadSheetOpacity,
        transition: 'none',
        zIndex: 10
      }}>
        
        {/* Simple Clean Header */}
        <div style={{ height: 72, backgroundColor: '#f3f2f1', borderBottom: `3px solid ${themeColor}`, display: 'flex', alignItems: 'center', padding: "0 24px" }}>
          <Img 
            src={LOGO_URL}
            style={{ height: 40, width: 'auto', objectFit: 'contain', marginRight: 16 }} 
          />
          <span style={{ fontSize: 20, fontWeight: 600, color: '#323130' }}>{documentTitle}</span>
          
          <div style={{ flex: 1 }} />
          
          <div style={{ padding: "8px 20px", backgroundColor: themeColor, color: 'white', borderRadius: 6, fontSize: 14, fontWeight: 600 }}>Share</div>
        </div>
        
        {/* Grid Area */}
        <div style={{ flex: 1, position: 'relative', overflow: 'hidden' }}>
          
          {/* Column Headers */}
          <div style={{ display: 'flex', backgroundColor: '#faf9f8', borderBottom: '1px solid #e1dfdd' }}>
            <div style={{ ...cellStyle, width: '10%', fontWeight: 600 }}>ID</div>
            <div style={{ ...cellStyle, width: '25%', fontWeight: 600 }}>Service</div>
            <div style={{ ...cellStyle, width: '25%', fontWeight: 600 }}>Username</div>
            <div style={{ ...cellStyle, width: '25%', fontWeight: 600 }}>Credentials</div>
            <div style={{ ...cellStyle, width: '15%', fontWeight: 600, borderRight: 'none' }}>Status</div>
          </div>
          
          {/* Rendered Data Rows */}
          {MOCK_DATA.slice(0, numberOfEntries).map((row, i) => {
            const rowDelay = 40 + i * 4;
            const rowSpring = spring({ frame: frame - rowDelay, fps, config: { damping: 14 } });
            const rowY = interpolate(rowSpring, [0, 1], [30, 0]);
            const rowOpacity = interpolate(frame - rowDelay, [0, 10], [0, 1], { extrapolateRight: 'clamp' });
            
            const isSelected = i === targetDataRowIndex;
            const displayString = showPasswordsAsAsterisks ? "••••••••••••" : row.pass;
            
            let renderedPass = displayString;
            let showCursor = false;

            if (isSelected) {
              const typeDelay = 65;
              const typeProgress = interpolate(frame - typeDelay, [0, 25], [0, displayString.length], { extrapolateRight: 'clamp', extrapolateLeft: 'clamp' });
              renderedPass = displayString.slice(0, Math.floor(typeProgress));
              
              // Blinking cursor active during and shortly after typing
              showCursor = frame >= typeDelay - 15 && frame % 30 < 15;
            }

            const cellHighlight = isSelected ? { 
              boxShadow: `inset 0 0 0 2px ${themeColor}`,
              backgroundColor: '#f3fdf6' 
            } : {};

            return (
              <div key={row.id} style={{ 
                display: 'flex', 
                borderBottom: '1px solid #e1dfdd',
                transform: `translateY(${rowY}px)`,
                opacity: rowOpacity,
                backgroundColor: '#ffffff',
                transition: 'none'
              }}>
                {/* Data Cells */}
                <div style={{ ...cellStyle, width: '10%', color: '#605e5c', fontFamily: monoFamily }}>{row.id}</div>
                <div style={{ ...cellStyle, width: '25%', fontWeight: 500 }}>{row.service}</div>
                <div style={{ ...cellStyle, width: '25%', fontFamily: monoFamily }}>{row.user}</div>
                
                {/* Password Cell with Highlight and Typing Logic */}
                <div style={{ ...cellStyle, width: '25%', fontFamily: monoFamily, color: themeColor, ...cellHighlight, position: 'relative', zIndex: isSelected ? 10 : 1, fontWeight: isSelected ? 600 : 400 }}>
                  {renderedPass}
                  {showCursor && <span style={{ display: 'inline-block', width: 2, height: 18, backgroundColor: themeColor, marginLeft: 2 }} />}
                  {isSelected && frame >= 90 && (
                    <div style={{ position: 'absolute', bottom: -1, right: -1, width: 6, height: 6, backgroundColor: themeColor, border: '1px solid #fff' }} />
                  )}
                </div>
                
                {/* Status Cell */}
                <div style={{ ...cellStyle, width: '15%', borderRight: 'none' }}>
                  <span style={{ 
                    backgroundColor: row.status === 'Active' ? '#dff6dd' : '#fde7e9',
                    color: row.status === 'Active' ? '#107c41' : '#a80000',
                    padding: '4px 8px',
                    borderRadius: 4,
                    fontSize: 12,
                    fontWeight: 600,
                    textTransform: 'uppercase'
                  }}>
                    {row.status}
                  </span>
                </div>
              </div>
            );
          })}
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default SharePointVault;